JSON;

    public function __construct(private readonly EnneagramPrivateResultPackLoader $loader) {}

    public function project(array $report): ?array
    {
        if (! in_array($report['scale_code'] ?? null, ['ENNEAGRAM', 'ENNEAGRAM_PERSONALITY_TEST'], true)) {
            return null;
        }
        $originalAuthority = data_get($report, '_meta.enneagram_private_result_authority');
        // Unknown, unversioned historical prose remains outside this finite canonical repair.
        if (data_get($originalAuthority, 'mode') !== 'canonical') {
            return null;
        }
        $original = data_get($report, '_meta.enneagram_report_v2');
        if (! is_array($original) || ($original['schema_version'] ?? null) !== 'enneagram.report.v2'
            || ($original['scale_code'] ?? null) !== 'ENNEAGRAM'
            || ! in_array(data_get($original, 'form.form_code'), ['enneagram_likert_105', 'enneagram_forced_choice_144'], true)
            || ! is_array($original['candidates'] ?? null) || ! is_array($original['modules'] ?? null) || ! is_array($original['pages'] ?? null)) {
            return $this->unavailable('canonical_report_structure_invalid');
        }
        $locales = [];
        foreach ([$report['locale'] ?? null, $original['locale'] ?? null, $originalAuthority['locale'] ?? null] as $value) {
            $normalized = match ($value) {
                'en' => 'en', 'zh', 'zh-CN' => 'zh-CN', default => null,
            };
            if ($normalized === null) {
                return $this->unavailable('locale_invalid_or_conflicting');
            }
            $locales[] = $normalized;
        }
        if (count(array_unique($locales)) !== 1
            || ($originalAuthority['source_hash'] ?? null) !== data_get($original, 'registry.source_hash')
            || ($originalAuthority['compiled_hash'] ?? null) !== data_get($original, 'registry.compiled_hash')) {
            return $this->unavailable('original_binding_invalid');
        }
        $locale = $locales[0];
        $loaded = $this->loader->load($locale);
        $rows = [];
        foreach (json_decode(self::FINGERPRINTS, true, 64, JSON_THROW_ON_ERROR) as $row) {
            if ($row['locale'] !== $locale) {
                continue;
            }
            $after = $this->sourceValue($loaded['assets'][$row['asset']] ?? [], $row);
            if (! is_string($after) || ! hash_equals($row['after_sha256'], hash('sha256', $after))) {
                return $this->unavailable('reading_source_drift');
            }
            $row['after'] = $after;
            $rows[] = $row;
        }
        $reading = $original;
        $applied = [];
        foreach ($reading['candidates'] as &$candidate) {
            if (! is_array($candidate) || ! is_array($candidate['sections'] ?? null)) {
                continue;
            }
            foreach ($candidate['sections'] as &$section) {
                if (! is_array($section)) {
                    continue;
                }
                foreach ($rows as $row) {
                    if ($row['asset'] !== 'chapter_registry.json'
                        || (string) ($candidate['type_id'] ?? '') !== $row['selector']['type_id']
                        || ($section['section_id'] ?? null) !== $row['selector']['section_id']) {
                        continue;
                    }
                    $path = $this->chapterPath($section, $row);
                    if ($path !== null) {
                        $this->replace($section, $path, $row, $applied);
                    }
                }
            }
            unset($section);
        }
        unset($candidate);
        $reading['modules'] = $this->modules($reading['modules'], $original, $rows, $applied);
        foreach ($reading['pages'] as &$page) {
            if (is_array($page['modules'] ?? null)) {
                $page['modules'] = $this->modules($page['modules'], $original, $rows, $applied);
            }
        }
        unset($page);
        $beforeStrings = array_fill_keys(array_column($rows, 'before'), true);
        if ($this->hasOld($reading, $beforeStrings)) {
            return $this->unavailable('unmatched_copy_identity');
        }
        if ($applied === []) {
            return null;
        }

        return ['schema_version' => 'enneagram.reading_copy.v1', 'revision' => self::REVISION, 'status' => 'ready',
            'locale' => $locale, 'original_authority' => $originalAuthority, 'reading_authority' => $loaded['authority'],
            'original_report_v2_sha256' => $this->digest($original), 'reading_report_v2_sha256' => $this->digest($reading),
            'applied_keys' => array_values(array_unique($applied)), 'report_v2' => $reading];
    }

    private function sourceValue(array $asset, array $row): mixed
    {
        if ($row['asset'] === 'ui_copy_registry.json') {
            return $this->at($asset['entries'][$row['selector']['ui_key']] ?? null, $row['tail']);
        }
        $key = $row['asset'] === 'chapter_registry.json' ? 'type_id' : 'pair_key';
        $entry = $this->one((array) ($asset['entries'] ?? []), $key, $row['selector'][$key]);
        if ($row['asset'] === 'pair_registry.json') {
            return $this->at($entry, $row['tail']);
        }
        $section = $this->one((array) ($entry['sections'] ?? []), 'section_id', $row['selector']['section_id']);
        $path = $this->chapterPath($section ?? [], $row);

        return $path === null ? null : $this->at($section, $path);
    }

    private function chapterPath(array $section, array $row): ?array
    {
        $path = $row['tail'];
        if (isset($row['selector']['level'])) {
            $indices = array_keys(array_filter((array) ($section['levels'] ?? []), static fn ($level): bool => is_array($level)
                && ($level['level'] ?? null) === $row['selector']['level']));
            if (count($indices) !== 1) {
                return null;
            }
            $path[1] = $indices[0];
        }

        return $path;
    }

    private function modules(array $modules, array $original, array $rows, array &$applied): array
    {
        foreach ($modules as &$module) {
            if (! is_array($module) || ($module['visibility'] ?? null) !== 'visible' || ! is_array($module['content'] ?? null)) {
                continue;
            }
            foreach ($rows as $row) {
                if ($row['asset'] === 'ui_copy_registry.json'
                    && ($module['module_key'] ?? null) === 'result_overview'
                    && $row['selector']['ui_key'] === 'result_overview.'.data_get($original, 'classification.interpretation_scope')
                    && in_array('enneagram_ui_copy_registry:'.$row['selector']['ui_key'], (array) ($module['registry_refs'] ?? []), true)) {
                    $this->replace($module, ['content', 'body'], $row, $applied);
                }
                if ($row['asset'] !== 'pair_registry.json' || ($module['module_key'] ?? null) !== 'candidate_pair_comparison'
                    || data_get($original, 'classification.interpretation_scope') !== 'close_call'
                    || data_get($module, 'content.available') !== true || data_get($module, 'content.pair_key') !== $row['selector']['pair_key']
                    || ! in_array('enneagram_pair_registry:'.$row['selector']['pair_key'], (array) ($module['registry_refs'] ?? []), true)) {
                    continue;
                }
                $ordered = array_map(static fn ($candidate): string => (string) ($candidate['type_id'] ?? ''), array_slice($original['candidates'], 0, 2));
                $moduleOrder = array_map(static fn ($candidate): string => (string) ($candidate['type_id'] ?? ''), (array) data_get($module, 'content.candidate_order', []));
                $sorted = $ordered;
                sort($sorted, SORT_NUMERIC);
                if ($moduleOrder !== $ordered || implode('_', $sorted) !== $row['selector']['pair_key']) {
                    continue;
                }
                $dimensionKey = $row['tail'][0] === 'core_motivation_difference' ? 'core_motivation' : 'core_concern';
                foreach ((array) data_get($module, 'content.dimensions', []) as $di => $dimension) {
                    if (($dimension['dimension_key'] ?? null) !== $dimensionKey) {
                        continue;
                    }
                    foreach ((array) ($dimension['sides'] ?? []) as $si => $side) {
                        if (($side['type_id'] ?? null) === $row['selector']['type_id']) {
                            $this->replace($module, ['content', 'dimensions', $di, 'sides', $si, 'copy'], $row, $applied);
                        }
                    }
                }
            }
        }
        unset($module);

        return $modules;
    }

    private function replace(array &$target, array $path, array $row, array &$applied): void
    {
        if ($this->at($target, $path) !== $row['before']) {
            return;
        }
        $leaf = &$target;
        foreach ($path as $key) {
            $leaf = &$leaf[$key];
        }
        $leaf = $row['after'];
        $applied[] = $row['asset'].':'.json_encode($row['selector']).':'.implode('.', $row['tail']);
    }

    private function one(array $items, string $key, string $value): ?array
    {
        $matches = array_values(array_filter($items, static fn ($item): bool => is_array($item) && (string) ($item[$key] ?? '') === $value));

        return count($matches) === 1 ? $matches[0] : null;
    }

    private function at(mixed $value, array $path): mixed
    {
        foreach ($path as $key) {
            if (! is_array($value) || ! array_key_exists($key, $value)) {
                return null;
            }
            $value = $value[$key];
        }

        return $value;
    }

    private function hasOld(mixed $value, array $before): bool
    {
        if (is_string($value)) {
            return isset($before[$value]);
        }
        foreach (is_array($value) ? $value : [] as $child) {
            if ($this->hasOld($child, $before)) {
                return true;
            }
        }

        return false;
    }

    private function unavailable(string $reason): array
    {
        return ['schema_version' => 'enneagram.reading_copy.v1', 'revision' => self::REVISION, 'status' => 'unavailable', 'reason' => $reason];
    }

    private function digest(array $report): string
    {
        return hash('sha256', \App\Services\ContentPromotion\PromotionContextFactory::canonicalJson($report));
    }
}
